// Parity with the Python publishers. Fixtures are generated by running the
// real backend functions (see CLAUDE.md → "Regenerating caption fixtures").

import { describe, expect, it } from "vitest";
import fixtures from "@/lib/captions/__fixtures__/publisher-parity.json";
import { buildLinkedInCommentary } from "@/lib/captions/linkedin";
import { buildMetaCaption } from "@/lib/captions/meta";
import { buildTelegramCaption } from "@/lib/captions/telegram";
import type { CaptionInput } from "@/lib/captions/types";

interface Fixture {
  name: string;
  title: string;
  subtitle: string;
  body: string;
  tags: string[];
  images: string[];
  expected: { telegram: string; instagram: string; facebook: string; linkedin: string };
}

function toInput(f: Fixture): CaptionInput {
  return { title: f.title, subtitle: f.subtitle, body: f.body, hashtagSource: f.tags, imageUrls: f.images };
}

describe.each(fixtures as Fixture[])("publisher parity: $name", (f) => {
  it("telegram", () => {
    expect(buildTelegramCaption(toInput(f)).text).toBe(f.expected.telegram);
  });
  it("instagram", () => {
    expect(buildMetaCaption(toInput(f)).text).toBe(f.expected.instagram);
  });
  it("facebook", () => {
    expect(buildMetaCaption(toInput(f)).text).toBe(f.expected.facebook);
  });
  it("linkedin", () => {
    expect(buildLinkedInCommentary(toInput(f)).text).toBe(f.expected.linkedin);
  });
});

describe("telegram truncation flag", () => {
  it.each([
    { name: "short_with_image", truncated: false },
    { name: "long_with_image_trims_body", truncated: true },
    { name: "long_text_only", truncated: true },
  ])("$name → truncated=$truncated", ({ name, truncated }) => {
    const f = (fixtures as Fixture[]).find((x) => x.name === name)!;
    expect(buildTelegramCaption(toInput(f)).truncated).toBe(truncated);
  });
});
